.darma-loader-darma-b11-rain-cloud { --accent: var(--loader-color, #38bdf8); --accent-2: var(--loader-secondary-color, #818cf8); width: var(--loader-size, 88px); height: var(--loader-size, 88px); position: relative; }
.darma-loader-darma-b11-rain-cloud .darma-loader-darma-b11-rain-cloud__cloud { position: absolute; top: 22%; left: 50%; width: 56%; height: 22%; margin-left: -28%; background: linear-gradient(#f1f5f9, #94a3b8); border-radius: 40px; }
.darma-loader-darma-b11-rain-cloud .darma-loader-darma-b11-rain-cloud__cloud::before { content: ''; position: absolute; bottom: 0; left: 12%; width: 42%; height: 150%; background: inherit; border-radius: 50%; }
.darma-loader-darma-b11-rain-cloud .darma-loader-darma-b11-rain-cloud__cloud::after { content: ''; position: absolute; bottom: 0; right: 10%; width: 50%; height: 130%; background: inherit; border-radius: 50%; }
.darma-loader-darma-b11-rain-cloud span { position: absolute; top: 52%; width: calc(var(--loader-size, 88px) * .04); height: calc(var(--loader-size, 88px) * .13); border-radius: 0 0 4px 4px; background: var(--accent); animation: darma-loader-darma-b11-rain-cloud-drop calc(var(--loader-speed, 1s) * 1) linear infinite; }
.darma-loader-darma-b11-rain-cloud span:nth-child(even) { background: var(--accent-2); }
.darma-loader-darma-b11-rain-cloud span:nth-child(1) { left: 32%; animation-delay: 0s; }
.darma-loader-darma-b11-rain-cloud span:nth-child(2) { left: 46%; animation-delay: calc(var(--loader-speed, 1s) * .35); }
.darma-loader-darma-b11-rain-cloud span:nth-child(3) { left: 60%; animation-delay: calc(var(--loader-speed, 1s) * .15); }
.darma-loader-darma-b11-rain-cloud span:nth-child(4) { left: 68%; animation-delay: calc(var(--loader-speed, 1s) * .55); }
@keyframes darma-loader-darma-b11-rain-cloud-drop { 0% { transform: translateY(0); opacity: 0; } 20% { opacity: 1; } 100% { transform: translateY(140%); opacity: 0; } }

